  "plans.intro": "একটি অ্যাকাউন্ট, যে পরিকল্পনাই বেছে নিন না কেন — Business পাঁচটি পর্যন্ত ব্যবসা কভার করে। দাম মার্কিন ডলারে মাসিক, এবং যোগ্য নতুন ওয়েবসাইট গ্রাহকরা Essentials ও Business জুড়ে একটি সাত দিনের ট্রায়াল পেতে পারেন। বিদ্যমান Essentials সাবস্ক্রিপশন Business-এ আপগ্রেড করলে ট্রায়াল আবার শুরু হয় না বা আরেকটি বিনামূল্যের ট্রায়াল তৈরি হয় না। ওয়েবসাইট পরিকল্পনার দাম প্রযোজ্য করের আগে, যদি থাকে। সাবস্ক্রিপশন অনুমোদন করার আগে আপনার সঠিক চার্জ দেখানো হবে।",
