  "upgrade.intro": "যোগ্য নতুন গ্রাহকরা প্রতি অ্যাকাউন্টে একটি {days} দিনের ট্রায়াল পেতে পারেন, প্রতি পরিকল্পনায় একটি করে নয়। Essentials থেকে Business-এ গেলে কখনো আরেকটি বিনামূল্যের ট্রায়াল শুরু হয় না। আপনি আছেন",
