  "upgrade.previewUpgradeNote": "আপগ্রেড করলে আপনার বিনামূল্যের ট্রায়াল কখনো আবার শুরু হয় না, এবং এতে দ্বিতীয় সাবস্ক্রিপশন তৈরি হয় না।",
