  "upgrade.upgradeNeverRestartsTrial": "আপগ্রেড করলে আপনার বিনামূল্যের ট্রায়াল কখনো আবার শুরু হয় না।",
  "upgrade.trialHistoryNote": "আপনি Essentials-এর জন্য অর্থ দিচ্ছেন এবং Business-এ গেলে, আপনি একই গ্রাহক অ্যাকাউন্ট ও ট্রায়ালের ইতিহাস রাখেন। Business-এ অতিরিক্ত সাত দিনের ট্রায়াল অন্তর্ভুক্ত নয়। মূল ট্রায়াল চলাকালীন আপগ্রেড করলে তার মূল শেষের তারিখ রিসেট হয় না।",
  "upgrade.providerConfirmNote": "পরিকল্পনার পরিবর্তনের জন্য বিলিং প্রদানকারীর নিশ্চিতকরণ প্রয়োজন। মূল্যের পার্থক্য, প্রোরেশন ও কার্যকর তারিখ পরিবর্তন অনুমোদন করার আগে দেখাতে হবে। আপগ্রেডে দ্বিতীয় একই সময়ের সাবস্ক্রিপশন তৈরি হওয়া উচিত নয়।",
  "upgrade.chargedThroughProviderNote": "পরিকল্পনার পরিবর্তনের চার্জ বিলিং প্রদানকারীর মাধ্যমে নেওয়া হয়। এই পাতায় আপনার বর্তমান পরিকল্পনার নিচে Cancel Subscription বোতাম দিয়ে, অথবা Settings থেকে আপনি আপনার সাবস্ক্রিপশন বাতিল করতে পারেন। বাতিল করলে আপনার অর্থপ্রদত্ত সময়ের শেষে ভবিষ্যতের নবায়ন বন্ধ হয়; এতে আপনার সুবিধা একসঙ্গে শেষ হয় না। বিদ্যমান বিনামূল্যের ওয়ার্কস্পেসগুলো এই বিকল্পগুলো দেখার জন্য চার্জ করা হয় না।",
  "billing.cancel.title": "সাবস্ক্রিপশন বাতিল করুন",
  "billing.cancel.description": "{plan} থেকে আনসাবস্ক্রাইব করুন। বাতিল করলে আপনার অর্থপ্রদত্ত সময়ের শেষে ভবিষ্যতের নবায়ন বন্ধ হয় — এতে আপনার সুবিধা একসঙ্গে শেষ হয় না।",
  "billing.cancel.yourPlan": "আপনার পরিকল্পনা",
