  "billing.cancel.doneWithEnd": "আপনার সম্পূর্ণ সুবিধা {endDate} পর্যন্ত থাকে। ওই তারিখের পর আপনার {graceDays} দিনের শুধু-পড়ার গ্রেস সময় থাকে — আপনি তখনো লগ ইন করে আপনার পণ্যগুলো দেখতে পারেন, কিন্তু যোগ করা, সম্পাদনা করা, মোছা, স্ক্যান করা, ইমপোর্ট, এক্সপোর্ট বা কিছু বদলানো যাবে না। {gracePart}",
  "billing.cancel.graceEndsOn": "15 দিনের গ্রেস সময় {date} শেষ হওয়ার পর, আপনার অ্যাকাউন্ট ও তার সমস্ত তথ্য স্থায়ীভাবে মুছে ফেলা হবে এবং তা আর ফেরত পাওয়া যাবে না।",
  "billing.cancel.doneNoEnd": "আপনার অর্থপ্রদত্ত সময়ের শেষ পর্যন্ত আপনার সম্পূর্ণ সুবিধা থাকে। তারপর 15 দিনের শুধু-পড়ার গ্রেস সময় প্রযোজ্য হয়। {wipeSentence}",
  "billing.cancel.refundWindowOpen": "আপনি প্রথম অর্থপ্রদত্ত চার্জের 3 দিনের মধ্যে বাতিল করেছেন, তাই ওই প্রথম পেমেন্টের ফেরতের জন্য আপনি যোগ্য হতে পারেন। বাতিল করলেই ফেরত দেওয়া হয় না — {contact}-এর মাধ্যমে অনুরোধ করুন।",
  "billing.cancel.refundWindowClosed": "বাতিল করলেই ফেরত দেওয়া হয় না। ফেরত প্রযোজ্য হয় কেবল প্রথম সফল অর্থপ্রদত্ত চার্জের 3 দিনের মধ্যে, {contact}-এর মাধ্যমে অনুরোধ করলে।",
