  "billing.readiness.title": "Essentials চেকআউট — প্রকৃত অ্যাকাউন্ট নিরাপত্তা পরীক্ষা",
  "billing.readiness.body": "কিছু না কিনে প্রকৃত সাবস্ক্রিপশন ও ট্রায়াল রেকর্ড পরীক্ষা করুন। আপনার বিনামূল্যের Business অ্যাকাউন্ট ও আপনার পাজামার নমুনা অপরিবর্তিত থাকে। এতে Stripe চেকআউট খোলে না, কার্ড থেকে টাকা কাটা হয় না, বা পরিকল্পনা বদলায় না।",
