  "billing.readiness.complimentaryProtected": "আপনার বিনামূল্যের Business ওয়ার্কস্পেস সুরক্ষিত। এটি অর্থপ্রদত্ত Essentials পরীক্ষার অ্যাকাউন্ট হওয়া উচিত নয়।",
  "billing.readiness.environmentIncomplete": "Stripe চেকআউটের শংসাপত্র, ওয়েবহুক যাচাইকরণ বা অ্যাপের ফেরত ঠিকানা সব নিশ্চিত করা যায়নি। কোনো চেকআউট শুরু হতে পারে না।",
  "billing.readiness.ownerHasHistory": "এই মালিকের আগের সাবস্ক্রিপশন বা ট্রায়ালের প্রমাণ আছে। দ্বিতীয় চেকআউট তৈরি করা উচিত নয়।",
  "billing.readiness.trialAlreadyUsed": "পরিচিতিমূলক ট্রায়াল ইতিমধ্যে ব্যবহার করা হয়েছে বা সংরক্ষিত আছে। পুনরায় ট্রায়াল শুরু হতে পারে না।",
