  "billing.readiness.auditUnavailable": "শুধু-পড়ার সার্ভার পরীক্ষা উপলব্ধ ছিল না। কোনো পেমেন্ট বা অ্যাকাউন্টের পরিবর্তন ঘটেনি।",
