  "billing.dryRun.body": "এই ব্রাউজারে সম্পূর্ণ কাল্পনিক রেকর্ড ব্যবহার করে প্রস্তাবিত আপগ্রেডের নিয়মগুলো অনুশীলন করুন। এতে আপনার আসল TEST — পাজামা প্যান্টের নমুনা, আপনার বর্তমান Business ওয়ার্কস্পেস, Stripe, ট্রায়াল, সাবস্ক্রিপশন বা ইনভেন্টরি পড়া বা বদলানো হয় না।",
