  "billing.dryRun.example": "উদাহরণ: Essentials ($14.99/মাস) → Business ($29.99/মাস), প্রযোজ্য করের আগে।",
  "billing.dryRun.preserved": "একই সাবস্ক্রিপশন রাখা হয়েছে, একটি মূল ট্রায়াল রাখা হয়েছে, এবং সিমুলেটেড পাজামা ইনভেন্টরি অপরিবর্তিত। উদাহরণের গ্রাহক Essentials-এই থাকেন যতক্ষণ না একটি আসল, প্রদানকারী-নিশ্চিত অর্থপ্রদত্ত নবায়ন সুবিধা বদলানোকে ন্যায্য করে।",
  "billing.dryRun.limitations": "স্থানীয় সিমুলেশন Stripe সাবস্ক্রিপশনের পরিবর্তন, পেমেন্ট, ওয়েবহুক, কর-সহ উদ্ধৃতি, লাইভ সাবস্ক্রিপশন বা আপনার প্রকৃত ব্যবসার রেকর্ড পরীক্ষা করে না।",
