  "exports.title": "এক্সপোর্ট ও ব্যাকআপ",
  "exports.subtitleStart": "ডাউনলোড সবসময় সীমাবদ্ধ থাকে",
  "exports.subtitleRest": " পর্যন্ত। প্রতিটি ফাইলে ব্যবসার নাম ও তৈরির তারিখ লেখা থাকে।",
  "exports.createBusinessFirst": "আগে একটি ব্যবসা তৈরি করুন — এক্সপোর্ট কোনো ব্যবসার অন্তর্গত, অ্যাপের নয়।",
  "exports.lockedTitle": "CSV ও Excel এক্সপোর্ট Business বৈশিষ্ট্য",
  "exports.lockedDesc": "আপনার ওয়ার্কস্পেস Essentials প্ল্যানে আছে। Business-এ CSV ও Excel এক্সপোর্ট, স্টক মূল্যায়ন, সীমাহীন পণ্য ও কর্মী, সরবরাহকারী, ক্রয় ও বান্ডেল যুক্ত হয়।",
  "exports.seeBusiness": "Business-এ কী কী আছে দেখুন",
  "exports.whatTheseAre": "এই ফাইলগুলো কী",
  "exports.about1": "প্রতিটি ডেটাসেট CSV অথবা আসল Excel ওয়ার্কবুক (.xlsx) হিসেবে আসে — সম্পূর্ণ ইনভেন্টরি ওয়ার্কবুক শুধু Excel-এ হয়, প্রতিটি ডেটাসেটের জন্য আলাদা শিট থাকে। CSV ফাইল Excel, Numbers, Google Sheets ও বেশিরভাগ স্টক অ্যাপে খোলে। UTF-8 টেক্সট, উদ্ধৃত কমা, নোটের ভেতরের লাইন ব্রেক ও কোডের শুরুর শূন্যগুলো সবই অক্ষত থাকে, আর সূত্রের মতো শুরু হওয়া সেলগুলো নিরপেক্ষ করে দেওয়া হয় যাতে স্প্রেডশিট সেগুলোকে টেক্সট হিসেবে খোলে।",
  "exports.about2": "Excel ফাইলে SKU, UPC, ISBN ও বারকোড টেক্সট সেল — কখনো বৈজ্ঞানিক নোটেশন নয়, কখনো ছাঁটা শূন্য নয় — কলামের প্রস্থ, হেডার ফিল্টার ও মুদ্রা বা পরিমাণের ফরম্যাট প্রয়োগ করা থাকে। সম্পূর্ণ ইনভেন্টরি ওয়ার্কবুকে পণ্য, স্টক স্তর, অবস্থান ও মুভমেন্ট আলাদা আলাদা শিটে থাকে।",
  "exports.about3": "খুব বড় এক্সপোর্ট প্রতিটি ডেটাসেটে 20,000 সারিতে থেমে যায় — তা হলে ফাইলের নামেই তা লেখা থাকে (truncated-20000), যাতে আংশিক ফাইল কখনো সম্পূর্ণ বলে মনে না হয়।",
  "exports.about4": "ব্যাকআপ আপনার ডেটার একটি স্ন্যাপশট, এক ক্লিকে পুনরুদ্ধার নয়। এটি ফিরিয়ে আনা হাতে করা, আগে পর্যালোচনা করা কাজ, তাই ফাইলটি নিরাপদে রাখুন — মুছে যাওয়া ব্যবসা এখান থেকে আবার তৈরি করার মতো কিছু অ্যাপে এখনো নেই। অ্যাপ কোড ও Base44 প্ল্যাটফর্মের ব্যাকআপ এই ফাইলগুলো থেকে আলাদাভাবে পরিচালিত হয়।",
  "exports.about5": "ছবি ও সংযুক্তিগুলো তাদের সংরক্ষিত লিঙ্ক হিসেবে তালিকাভুক্ত হয় — ছবির ফাইলগুলো নিজে ডাউনলোডে প্যাক করা হয় না।",
  "exports.backupTitle": "সম্পূর্ণ ব্যাকআপ",
  "exports.backupDesc": "এই ব্যবসার পণ্য, অবস্থান, স্টক স্তর, সম্পূর্ণ মুভমেন্ট লেজার, সরবরাহকারী, ক্রয়, অর্ডার, রিটার্ন, গণনা ও তালিকা — সাথে তার প্রোফাইল সেটিংস — একটিই ফাইলে। এমন জায়গায় রাখুন যা আপনার নিয়ন্ত্রণে আছে।",
