  "import.createDesc": "ক্যাটালগে এখনো নেই এমন সারি যোগ করে। ইতিমধ্যে ব্যবহৃত ডুপ্লিকেট SKU ও বারকোড এড়িয়ে যাওয়া হয়, আর শুরুর স্টক আপনার বেছে নেওয়া অবস্থানে রসিদ হিসেবে যেতে পারে।",
  "import.updateTitle": "বিদ্যমান পণ্য আপডেট করুন",
  "import.updateDesc": "প্রতিটি সারি SKU বা রেকর্ড ID দিয়ে মেলায় এবং পুরনো মানের পাশে প্রস্তাবিত নতুন মান দেখায়। ফাঁকা সেল সংরক্ষিত মান অপরিবর্তিত রাখে, যদি না আপনি ফাঁকাগুলো মুছে দিতে বলেন, আর পরিমাণ কখনো ছোঁয়া হয় না।",
  "import.receiveModeTitle": "স্টক গ্রহণ করুন",
  "import.receiveModeDesc": "আগত পরিমাণ একটি অবস্থানে যোগ করে এবং প্রতিটি লাইনের জন্য মুভমেন্ট লেজারে রসিদ লেখে। প্রতিটি ব্যাচ চিহ্নিত করা হয়, তাই একই শিট দুবার গ্রহণ করা যায় না।",
  "import.excelNote": "Excel ওয়ার্কবুক (.xlsx) সরাসরি পড়া হয় — ওয়ার্কশিট বেছে নিন আর কলামগুলো আপনার জন্য মিলিয়ে দেওয়া হয়। কোডগুলো অক্ষত থাকে: টেক্সট হিসেবে সংরক্ষিত UPC তার সংখ্যা ও শুরুর শূন্য ধরে রাখে। যে সারিগুলো ইমপোর্ট করা যায় না সেগুলো কারণসহ তালিকাভুক্ত হয়",
