  "valuation.footnote": "খরচের মূল্যে প্রতিটি পণ্যের বর্তমান ইউনিট খরচ ব্যবহার করা হয়, তাই নতুন দামে গ্রহণ করলে পুরো তাকের মূল্য আবার নির্ধারিত হয়। রাখা ইউনিটগুলো এখানেও গোনা হয় — সেগুলো হাতে আছে, শুধু একটি অর্ডারের জন্য প্রতিশ্রুত। অনুপস্থিত অর্থ কখনো শূন্য ধরা হয় না; সংখ্যাটি জানা না যাওয়া পর্যন্ত ফিল্ডটি ফাঁকা রাখুন।",
