  "print.pickReturnHint": "নথির প্রিভিউ দেখতে তালিকা থেকে একটি লগ করা রিটার্ন বেছে নিন।",
  "print.chooseStyleHint": "একটি ধরন বেছে নিন, তারপর তালিকা থেকে পণ্য বেছে নিন। প্রিভিউতে প্রিন্টার থেকে ঠিক যা বেরোবে তাই দেখা যায়।",
  "print.howToReach": "আপনার প্রিন্টারে কীভাবে পৌঁছাবেন",
  "print.howIntro": "এই অ্যাপ আপনার ইতিমধ্যে থাকা প্রিন্টারগুলোর সাথে সংযোগ করে — এটি নিজে প্রিন্টার নয়। সেখানে পৌঁছানোর চারটি উপায় আছে, আর লেবেল দুটি প্ল্যানেই যেকোনো উপায়ে প্রিন্ট হয়। প্যাকিং স্লিপ, ক্রয় অর্ডার, সরবরাহকারীর নথি ও রিপোর্ট যেকোনো সংযোগেই Business-শুধু।",
  "print.howBluetoothLead": "Bluetooth।",
  "print.howBluetoothBody": "এই পৃষ্ঠা থেকে, ডেস্কটপ Chrome বা Edge-এ এবং Android Chrome-এ: আপনার লেবেল প্রিন্টারটি বেছে নিন আর লেবেলগুলো সরাসরি সেখানে যাবে। iOS Safari-তে এটি কাজ করে না — iPhone-এ Bluetooth প্রিন্টিং মোবাইল অ্যাপের সাথে আসে। যে প্রিন্টার শুধু Zebra ZPL বা Brother-এর নিজস্ব ভাষা বোঝে, সে এই পৃষ্ঠা থেকে পাঠানো লেবেল বুঝবে না; কাজ করছে বলার আগে আসল প্রিন্টারে তা পরীক্ষা করা হয়।",
  "print.howWifiLead": "Wi-Fi।",
  "print.howWifiBody": "আপনার দোকানের Wi-Fi-তে প্রিন্টারটি ইনস্টল করুন, তারপর প্রিন্ট বোতামটি ব্যবহার করুন — এটি এই কম্পিউটারে ইনস্টল করা প্রিন্টারের মাধ্যমে, দোকানের নেটওয়ার্ক দিয়ে প্রিন্ট করে। iPhone-এ AirPrint অন্তর্নির্মিত: একই Wi-Fi-তে থাকা একটি AirPrint প্রিন্টার প্রিন্ট শিটে এমনিই দেখা যায়, কোনো কর্ড বা অ্যাপ দরকার নেই, আর অ্যাপের AirPrint-নির্দিষ্ট কোনো কোডের দরকার নেই। প্রিন্টারটিকে AirPrint সমর্থন করতে হবে (বেশিরভাগ নতুন প্রিন্টার করে) এবং ফোন ও প্রিন্টার একই Wi-Fi-তে থাকতে হবে।",
  "print.howEthernetLead": "Ethernet।",
  "print.howEthernetBody": "Ethernet কর্ড দিয়ে প্রিন্টারটিকে আপনার দোকানের নেটওয়ার্কে তার দিয়ে যুক্ত করুন, কম্পিউটারে ইনস্টল করুন, আর প্রিন্ট বোতামের মাধ্যমে প্রিন্ট করুন। Ethernet ডেস্কটপ ও কম্পিউটারের পথ — iPhone Ethernet কর্ড ব্যবহার করে না।",
  "print.howUsbLead": "USB।",
  "print.howUsbBody": "প্রিন্টারটিকে তার কর্ড দিয়ে কম্পিউটারে প্লাগ করুন আর প্রিন্ট বোতামটি ব্যবহার করুন — এটি সেখানে ইনস্টল করা প্রিন্টারের মাধ্যমে প্রিন্ট করে। USB OTG কেবলসহ Android ফোনে উপরের USB বোতামটি সরাসরি প্রিন্টারের সাথে কথা বলে। iPhone USB দিয়ে সরাসরি প্রিন্ট করতে পারে না — সেখানে কোনো WebUSB নেই — তাই Wi-Fi / AirPrint, অথবা মোবাইল অ্যাপ থেকে Bluetooth ব্যবহার করুন।",
  "print.howCordsLead": "কর্ডগুলো iPhone-এর কাজে আসে, এক ধাপ দূর থেকে।",
  "print.howCordsBody": "দোকানের কম্পিউটারে প্লাগ করা একটি USB প্রিন্টার, অথবা নেটওয়ার্কে তার দিয়ে যুক্ত একটি Ethernet প্রিন্টার, দোকানের Wi-Fi দিয়ে আপনার iPhone-এ দেখা যায় (AirPrint / শেয়ার করা প্রিন্টার) — কর্ডগুলো প্রিন্টারটিকে নেটওয়ার্কে দৃঢ়ভাবে বসায়, আর ফোনটি তাতে তারবিহীনভাবে পৌঁছায়।",
  "print.howOfflineLead": "ইন্টারনেট চলে গেলে,",
  "print.howOfflineBody": "এই পৃষ্ঠায় ইতিমধ্যে থাকা লেবেল ও নথিগুলো তবুও প্রিন্ট হয় — প্রিন্ট বোতাম, লেবেল PDF, Bluetooth ও USB-এর কোনো সংযোগ দরকার নেই। যেটির ইন্টারনেট দরকার তা হলো প্রথমে পৃষ্ঠা ও এর পণ্যগুলো লোড করা। সম্পূর্ণ অফলাইন মোড (কোনো সংযোগ ছাড়াই অ্যাপে কাজ করা) একটি আলাদা, বড় কাজ এবং এখানে তা দাবি করা হচ্ছে না।",
